def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    # separator colour: every cell of it lies in a full uniform column of it
    full_cols = {}
    for x in range(W):
        vals = set(g[:, x].tolist())
        if len(vals) == 1:
            c = g[0, x]
            full_cols.setdefault(int(c), []).append(x)
    sep_colour = None
    for c, xs in full_cols.items():
        if c != bg and int((g == c).sum()) == len(xs) * H:
            sep_colour = c
            break
    seps = full_cols.get(sep_colour, []) if sep_colour is not None else []
    bounds = [-1] + sorted(seps) + [W]
    pans = {}
    for a, b in zip(bounds[:-1], bounds[1:]):
        if b - a <= 1:
            continue
        p = g[:, a + 1:b]
        cols = [int(c) for c in np.unique(p) if c != bg]
        if len(cols) == 1:
            pans[cols[0]] = p
    h, w = next(iter(pans.values())).shape
    out = np.full((h, w), bg, dtype=int)
    emit(out.copy(), "Start with an empty canvas the size of one panel.")
    for c in [5, 8, 4, 9]:  # lowest to highest priority
        if c in pans:
            out[pans[c] == c] = c
            emit(out.copy(), f"Overlay the colour-{c} panel; it overwrites lower-priority colours.")
    return out
